import subprocess
from fractions import Fraction
def kept(f_str, seed=11, idx='s1'):
    p=subprocess.run(["./executable","seq","-s",str(seed),"-f",f_str,"/tmp/t/div.fa"],stdout=subprocess.PIPE)
    return (b'>'+idx.encode()) in p.stdout
def estimate(seed=11, idx='s1', iters=45):
    lo,hi=Fraction(0),Fraction(1)
    for _ in range(iters):
        m=(lo+hi)/2
        # decimal string high precise
        s='%.15f'%(float(m))
        # use float value actually parsed; track based on s float fraction
        mf=Fraction(float(s)).limit_denominator(10**18) # messy
        if kept(s,seed,idx): hi=Fraction(float(s))
        else: lo=Fraction(float(s))
    return lo,hi
for idx in ['s1','s2']:
    lo,hi=estimate(idx=idx, iters=40)
    mid=(lo+hi)/2
    print(idx, float(mid), "width", float(hi-lo))
    for bits in [31,32,48,53,24,26]:
        scaled=mid*(1<<bits)
        print(" bits",bits, float(scaled), "nearest err", float(scaled-round(float(scaled))))
    for den_name,den in [("2^31-1",2**31-1),("2^32-1",2**32-1)]:
        scaled=mid*den
        print(" den",den_name, float(scaled), float(scaled-round(float(scaled))))
PY"}

