import subprocess
def kept(f,seed=11,idx='s1'):
    p=subprocess.run(["./executable","seq","-s",str(seed),"-f",repr(f),"/tmp/t/div.fa"],stdout=subprocess.PIPE)
    return (b'>'+idx.encode()) in p.stdout
def exact48(seed,idx):
    lo=0; hi=1<<48  # invariant: f=lo/2^48 not kept, hi kept
    while hi-lo>1:
        m=(lo+hi)//2
        if kept(m/(1<<48),seed,idx): hi=m
        else: lo=m
    return lo,hi
for idx in ['s1','s2','s3','s4','s5','s6','s7','s8']:
    lo,hi=exact48(11,idx)
    print(idx, lo, hi, hex(lo), lo/(1<<48))
