# reuse exact via sample for specific indices 17,27
import subprocess, struct
def d2i(d): return struct.unpack('<Q', struct.pack('<d', d))[0]
def i2d(i): return struct.unpack('<d', struct.pack('<Q', i))[0]
def kept(f,idx):
    p=subprocess.run(["./executable","sample","/tmp/t/m100.fa",repr(f)],stdout=subprocess.PIPE)
    return f">s{idx}\n".encode() in p.stdout
def exact(idx):
    lo=d2i(0.0); hi=d2i(0.9999999999999999)
    while hi-lo>1:
        m=(lo+hi)//2
        if kept(i2d(m),idx): hi=m
        else: lo=m
    return i2d(lo)
from fractions import Fraction
for idx in [17,27,4,11]:
