import subprocess
def intervals(args):
    p=subprocess.run(["./executable","seq"]+args+["/tmp/t/qrange.fq"],stdout=subprocess.PIPE)
    seq=p.stdout.decode().splitlines()[1]
    vals=[i for i,c in enumerate(seq) if c.islower()] # qual=i because ascii 33+i
    # intervals
    res=[]
    for v in vals:
        if not res or v>res[-1][1]+1: res.append([v,v])
        else: res[-1][1]=v
    return res
for X in [40,41,45,50,60,70,80,90,100,200,1000]:
    print("X",X, intervals(["-q","10","-X",str(X)]))
for q in [5,10,20]:
  for X in [50,100]:
    print("q",q,"X",X, intervals(["-q",str(q),"-X",str(X)]))
PY"}

