import subprocess
def intervals(args):
    p=subprocess.run(["./executable","seq"]+args+["/tmp/t/qrange.fq"],stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    lines=p.stdout.decode().splitlines()
    if len(lines)<2: return (lines,p.stderr)
    seq=lines[1]; vals=[i for i,c in enumerate(seq) if c.islower()]
    res=[]
    for v in vals:
        if not res or v>res[-1][1]+1: res.append([v,v])
        else: res[-1][1]=v
    return res
for args in [["-q","-1","-X","50"],["-q","0","-X","50"],["-q","1","-X","50"],["-X","50"],["-q","10"],["-q","10","-X","0"],["-q","10","-X","-10"]]:
    print(args, intervals(args))
# impact of Q offset on X threshold
for Q in [33,64,0]:
    print("Q",Q, intervals(["-Q",str(Q),"-q","10","-X","50"]))
PY"}

