import subprocess,random

def orig(seq,f=0.6,x=10.0,l=20,w=False):
    open('/tmp/t/gc.fa','w').write('>x\n'+seq+'\n')
    args=["gc","-f",str(f),"-x",str(x),"-l",str(l)]
    if w: args.insert(1,"-w")
    p=subprocess.run(["./executable"]+args+["/tmp/t/gc.fa"],stdout=subprocess.PIPE)
    return [(int(a),int(b),int(c)) for _,a,b,c in (line.split('\t') for line in p.stdout.decode().splitlines())]

def sim(seq,f=0.6,X=10.0,minlen=20,w=False):
    target_set=set('ATWatw' if w else 'CGScgs')
    is_t=[c in target_set for c in seq]
    ts=(1.0/f-1.0) if f!=0 else float('inf')
    n=len(seq); out=[]
    beg=0;i=0;score=0.0;max_score=0.0;max_end=0
    def emit(b,e):
        if e-b>=minlen: out.append((b,e,sum(is_t[b:e])))
    while i<n:
        score += ts if is_t[i] else -1.0
        if score>max_score:
            max_score=score;max_end=i+1
        if score<0 or max_score-score>X:
            if max_score>0:
                emit(beg,max_end)
                i=max_end;beg=max_end
            else:
                i+=1;beg=i
            score=0.0;max_score=0.0;max_end=beg
            continue
        i+=1
    if max_score>0: emit(beg,max_end)
    return out

def test_random(trials=200):
    bad=0
    for trial in range(trials):
        rng=random.Random(trial)
        # generate blocks
        seq=''
        while len(seq)<120:
            seq+=rng.choice('ACGT')*rng.randint(1,20)
        seq=seq[:rng.randint(50,120)]
        f=rng.choice([0.4,0.5,0.6,0.7,0.8]); x=rng.choice([1,5,10,20]); l=rng.choice([5,10,20])
        o=orig(seq,f,x,l); s=sim(seq,f,x,l)
        if o!=s:
            bad+=1; print('MISMATCH',trial,'f',f,'x',x,'l',l); print(seq); print('orig',o); print('sim',s)
            if bad>=10: break
    print('bad',bad,'/',trials)
test_random(200)
