    ts=(1.0/f-1.0) if f!=0 else float('inf'); n=len(seq); out=[]
    beg=0;i=0;score=0.0;max_score=0.0;max_end=0
    def emit(b,e):
        if e-b>=minlen: out.append((b,e,sum(is_t[b:e])))
    while i<n:
        score += ts if is_t[i] else -1.0
        if score>max_score: max_score=score;max_end=i+1
        if max_score-score>X:
            if max_score>0: emit(beg,max_end)
