            mt = self.mt
            for i in range(self.NN - self.MM):
                x = (mt[i] & self.UM) | (mt[i+1] & self.LM)
                mt[i] = mt[i+self.MM] ^ (x >> 1) ^ (self.MATRIX_A if (x & 1) else 0)
            for i in range(self.NN - self.MM, self.NN - 1):
                x = (mt[i] & self.UM) | (mt[i+1] & self.LM)
                mt[i] = mt[i+self.MM-self.NN] ^ (x >> 1) ^ (self.MATRIX_A if (x & 1) else 0)
