        if comment:
            self.comment_buffer = comment
        seq_parts = []
        is_plus = False
        while True:
            if self.pos >= len(self.data):
                break
            line = self._read_line()
            if line is None:
                break
            if line[:1] == b'>' or line[:1] == b'@':
                self.pending = line
                break
            if line[:1] == b'+':
                is_plus = True
                break
            seq_parts.append(line)
        seq = b''.join(seq_parts)
        qual = None
        if is_plus:
            qparts = []
            qlen = 0
            valid = True
            while qlen < len(seq):
                line = self._read_line()
                if line is None:
                    valid = False
                    break
                qparts.append(line)
                qlen += len(line)
            if (not valid) or qlen != len(seq):
                self.exhausted = True
                return None
            qual = b''.join(qparts)
        return SeqRecord(name, comment, self.comment_buffer, seq, qual)

def iter_records(data):
    return SeqParser(data)

# ---------- printing ----------
def write_wrapped(out, seq, line_len):
    if line_len and line_len > 0:
        for i in range(0, len(seq), line_len):
            out.write(seq[i:i+line_len] + b'\n')
    else:
        out.write(seq + b'\n')

def print_record(out, name, comment, seq, qual, line_len=0, force_fasta=False, fake_char=0, qual_shift=0):
    is_fq = (not force_fasta) and (fake_char != 0 or (qual is not None and len(qual) > 0))
    out.write((b'@' if is_fq else b'>') + name)
    if comment:
        out.write(b' ' + comment)
    out.write(b'\n')
    write_wrapped(out, seq, line_len)
    if is_fq:
        out.write(b'+\n')
        if fake_char:
            q = bytes([fake_char]) * len(seq)
        else:
            q = qual if qual is not None else b''
        if qual_shift:
            q = bytes(((c + qual_shift) & 0xff) for c in q)
        write_wrapped(out, q, line_len)

def print_record_obj(out, rec, **kw):
    print_record(out, rec.name, rec.comment, rec.seq, rec.qual, **kw)

def print_fasta60(out, name, seq):
    out.write(b'>' + name + b'\n')
    for i in range(0, len(seq), 60):
        out.write(seq[i:i+60] + b'\n')

# complement table
_comp = list(range(256))
_pairs = [(b'A',b'T'),(b'C',b'G'),(b'B',b'V'),(b'D',b'H'),(b'K',b'M'),(b'R',b'Y')]
for _a,_b in _pairs:
    _comp[_a[0]] = _b[0]; _comp[_b[0]] = _a[0]
    _comp[_a[0]+32] = _b[0]+32; _comp[_b[0]+32] = _a[0]+32
_comp[ord('U')] = ord('A'); _comp[ord('u')] = ord('a')
_comp[96] = 64  # backtick -> @ quirk
COMP_TABLE = bytes(_comp)

def revcomp(seq):
    return seq.translate(COMP_TABLE)[::-1]

def to_upper_byte(c):
    return c - 32 if 97 <= c <= 122 else c

# ---------- getopt (GNU-like permutation) ----------
class Getopt:
    def __init__(self, prog, args, spec):
        # spec string: char, char+':' for required arg
        self.spec = {}
        i = 0
        while i < len(spec):
            ch = spec[i]
            if i + 1 < len(spec) and spec[i+1] == ':':
                self.spec[ch] = True
                i += 2
            else:
                self.spec[ch] = False
                i += 1
        self.opts = []      # list of (char, arg_or_None); '?' for errors
        self.args = []      # positionals
        pos = 0
        n = len(args)
        end_opts = False
        while pos < n:
            tok = args[pos]
            if end_opts or tok == '-' or not tok.startswith('-') or tok == '':
                self.args.append(tok)
                pos += 1
                continue
            if tok == '--':
                end_opts = True
                pos += 1
                continue
            # option cluster
            j = 1
            consumed_next = False
            while j < len(tok):
                ch = tok[j]
                if ch not in self.spec:
                    err_bytes("%s: invalid option -- '%s'\n" % (prog, ch))
                    self.opts.append(('?', None))
                    j += 1
                    continue
                if self.spec[ch]:
                    # requires arg
                    if j + 1 < len(tok):
                        self.opts.append((ch, tok[j+1:]))
                    elif pos + 1 < n:
                        self.opts.append((ch, args[pos+1]))
                        consumed_next = True
                    else:
                        err_bytes("%s: option requires an argument -- '%s'\n" % (prog, ch))
                        self.opts.append(('?', None))
                    break
                else:
                    self.opts.append((ch, None))
                    j += 1
            pos += 2 if consumed_next else 1

def first_byte(s):
    if s is None or len(s) == 0:
        return 0
    b = os.fsencode(s)
    return b[0] if b else 0

# ---------- region (BED/list) handling ----------
def _parse_int_token(tok):
    """Return int if tok looks like a C integer parsed by seqtk's scanner:
    starts with digit, or '-' followed by digit.  Trailing junk ignored (atoi).
    Otherwise None."""
    if not tok:
        return None
    s = tok.decode('latin1')
    if s[0].isdigit() or (s[0] == '-' and len(s) > 1 and s[1].isdigit()):
        return c_atoi(s)
    return None

class Region:
    __slots__ = ('beg','end','strand')
    def __init__(self, beg, end, strand=b'+'):
        self.beg = beg; self.end = end; self.strand = strand

def _store_region(beg_raw, end_raw, strand=b'+'):
    if beg_raw is None:
        return Region(-1, -1, strand)
    if end_raw is None or end_raw < 0:
        if beg_raw > 0:
            return Region(beg_raw - 1, beg_raw, strand)
        else:
            return Region(beg_raw, -1, strand)
    return Region(beg_raw, end_raw, strand)

def load_regions(path, tab_only=False):
    """Return dict name->list[Region], or None on failure."""
    data = read_aux_data(path)
    if data is None:
        return None
    regions = {}
    for raw_line in data.split(b'\n'):
        line = raw_line.rstrip(b'\r')
        if line == b'':
            continue
        if tab_only:
            toks = line.split(b'\t')
        else:
            toks = line.split()
        if not toks:
            continue
        name = toks[0]
        beg_raw = _parse_int_token(toks[1]) if len(toks) >= 2 else None
        end_raw = None
        if beg_raw is not None and len(toks) >= 3:
            end_raw = _parse_int_token(toks[2])
            if end_raw is None:
                # treat as missing end
                end_raw = -1
        strand = b'+'
        if tab_only and len(toks) >= 6 and toks[5][:1] == b'-':
            strand = b'-'
        elif (not tab_only) and len(toks) >= 6 and toks[5][:1] == b'-':
            strand = b'-'
        reg = _store_region(beg_raw, end_raw, strand)
        regions.setdefault(name, []).append(reg)
    return regions

def effective_region(reg, length):
    """Return (beg,end,whole_flag) where whole_flag True for name-only regions."""
    if reg.beg < 0:
        return (0, length, True)
    if reg.end < 0:
        return (0, length, False)
    beg = reg.beg
    end = reg.end if reg.end < length else length
    return (beg, end, False)

