def _comp_counts(seq, upper_only):
    # returns [A,C,G,T,amb2,amb3,other,cpg,tv,ts,cpg_het]
    cnt = [0]*11
    def norm(c):
        if upper_only and 97 <= c <= 122:
            return None
        return to_upper_byte(c)
    prev = None
    for c in seq:
        u = norm(c)
        if u is None:
            prev = None
            continue
        ch = chr(u)
        if ch == 'A': cnt[0] += 1
        elif ch == 'C': cnt[1] += 1
        elif ch == 'G': cnt[2] += 1
        elif ch == 'T': cnt[3] += 1
        elif ch in 'RYMKSW':
            cnt[4] += 1
            if ch in 'MKSW': cnt[8] += 1
            else: cnt[9] += 1
        elif ch in 'BDHV': cnt[5] += 1
        else: cnt[6] += 1
        if prev is not None:
            p = chr(prev)
            if p in 'CY' and ch in 'GR':
                cnt[7] += 2
                cnt[10] += (1 if p == 'Y' else 0) + (1 if ch == 'R' else 0)
        prev = u
    return cnt

