# ================= subcommands =================

def cmd_seq(args):
    go = Getopt('seq', args, "acrxACNRSUV12f:l:n:q:s:F:L:M:Q:X:")
    flag_a = False; flag_c = False; flag_r = False; flag_x = False
    flag_C = False; flag_N = False; flag_R = False; flag_U = False; flag_V = False
    flag_1 = False; flag_2 = False
    frac = None; line_len = 0; mask_char = 0; qthresh = 0; seed = 11
    fake_char = 0; min_len = 0; mask_bed = None; qoffset = 33; max_qual = None
    for ch, val in go.opts:
        if ch == 'a' or ch == 'A': flag_a = True
        elif ch == 'c': flag_c = True
        elif ch == 'r': flag_r = True
        elif ch == 'x': flag_x = True
        elif ch == 'C': flag_C = True
        elif ch == 'N': flag_N = True
        elif ch == 'R': flag_R = True
        elif ch == 'S': pass
        elif ch == 'U': flag_U = True
        elif ch == 'V': flag_V = True
        elif ch == '1': flag_1 = True
        elif ch == '2': flag_2 = True
        elif ch == 'f': frac = c_atof(val)
        elif ch == 'l': line_len = c_atoi(val)
        elif ch == 'n': mask_char = first_byte(val)
        elif ch == 'q': qthresh = c_atoi(val)
        elif ch == 's': seed = c_atoi(val)
        elif ch == 'F': fake_char = first_byte(val)
        elif ch == 'L': min_len = c_atoi(val)
        elif ch == 'M': mask_bed = val
        elif ch == 'Q': qoffset = c_atoi(val)
        elif ch == 'X': max_qual = c_atoi(val)
    regions = None
    if mask_bed is not None:
        regions = load_regions(mask_bed, tab_only=False)
        # if load failed, regions stays None -> masking disabled
    data = read_input_data(go.args[0] if go.args else None, 'seq')
    rng = MT64(seed) if frac is not None else None
    out = sys.stdout.buffer
    idx = 0
    for rec in iter_records(data):
        my_idx = idx; idx += 1
        seq = bytearray(rec.seq)
        qual = rec.qual
        # length filter before RNG (observed)
        if min_len and len(seq) < min_len:
            continue
        if rng is not None:
            r = rng.real2()
            if not (r < frac):
                continue
        if flag_N:
            bad = False
            for c in seq:
                u = to_upper_byte(c)
                if u not in b'ACGT':
                    bad = True; break
            if bad:
                continue
        if flag_1 and (my_idx % 2 == 1):
            continue
        if flag_2 and (my_idx % 2 == 0):
            continue
        # quality masking
        if qthresh > 0 and qual is not None:
            n = min(len(seq), len(qual))
            for i in range(n):
                qc = qual[i]
                if (qc - qoffset < qthresh) or (max_qual is not None and qc > max_qual):
                    if mask_char: seq[i] = mask_char
                    elif 65 <= seq[i] <= 90: seq[i] += 32
        if flag_U:
            for i in range(len(seq)):
                seq[i] = to_upper_byte(seq[i])
        if flag_x:
            for i in range(len(seq)):
                if 97 <= seq[i] <= 122:
                    if mask_char: seq[i] = mask_char
                    # else already lowercase
        if regions is not None:
            regs = regions.get(rec.name, [])
            masked = [False] * len(seq)
            for reg in regs:
                beg, end, whole = effective_region(reg, len(seq))
                if beg < 0: beg = 0
                if end > len(seq): end = len(seq)
                for i in range(beg, end if end >= beg else beg):
                    masked[i] = True
            for i in range(len(seq)):
                m = masked[i]
                if flag_c: m = not m
                if m:
                    if mask_char: seq[i] = mask_char
                    elif 65 <= seq[i] <= 90: seq[i] += 32
        comment = None if flag_C else rec.comment
        shift = (33 - qoffset) if flag_V else 0
        seq_b = bytes(seq)
        if flag_R:
            print_record(out, rec.name + b'+', comment, seq_b, qual, line_len=line_len, force_fasta=flag_a, fake_char=fake_char, qual_shift=shift)
            rc_seq = revcomp(seq_b)
            rc_qual = qual[::-1] if qual is not None else None
            print_record(out, rec.name + b'-', comment, rc_seq, rc_qual, line_len=line_len, force_fasta=flag_a, fake_char=fake_char, qual_shift=shift)
        elif flag_r:
            rc_seq = revcomp(seq_b)
            rc_qual = qual[::-1] if qual is not None else None
            print_record(out, rec.name, comment, rc_seq, rc_qual, line_len=line_len, force_fasta=flag_a, fake_char=fake_char, qual_shift=shift)
        else:
            print_record(out, rec.name, comment, seq_b, qual, line_len=line_len, force_fasta=flag_a, fake_char=fake_char, qual_shift=shift)
    return 0

def cmd_size(args):
    data = read_input_data(args[0] if args else None, 'size')
    n = 0; total = 0
    for rec in iter_records(data):
        n += 1; total += len(rec.seq)
    out_bytes("%d\t%d\n" % (n, total))
    return 0

def _comp_counts(seq, upper_only):
    # returns [A,C,G,T,amb2,amb3,other,cpg,tv,ts,cpg_het]
    cnt = [0]*11
    def norm(c):
        if upper_only and 97 <= c <= 122:
            return None
        return to_upper_byte(c)
    prev = None
    for c in seq:
        u = norm(c)
        if u is None:
            prev = None
            continue
        ch = chr(u)
        if ch == 'A': cnt[0] += 1
        elif ch == 'C': cnt[1] += 1
        elif ch == 'G': cnt[2] += 1
        elif ch == 'T': cnt[3] += 1
        elif ch in 'RYMKSW':
            cnt[4] += 1
            if ch in 'MKSW': cnt[8] += 1
            else: cnt[9] += 1
        elif ch in 'BDHV': cnt[5] += 1
        else: cnt[6] += 1
        if prev is not None:
            p = chr(prev)
            if p in 'CY' and ch in 'GR':
                cnt[7] += 2
                cnt[10] += (1 if p == 'Y' else 0) + (1 if ch == 'R' else 0)
        prev = u
    return cnt

def cmd_comp(args):
    go = Getopt('comp', args, "r:u")
    bed = None; upper_only = False; has_r = False
    for ch, val in go.opts:
        if ch == 'r': bed = val; has_r = True
        elif ch == 'u': upper_only = True
    regions = None
    if has_r:
        regions = load_regions(bed, tab_only=False)
    data = read_input_data(go.args[0] if go.args else None, 'comp')
    out = sys.stdout.buffer
    for rec in iter_records(data):
        if regions is not None:
            for reg in regions.get(rec.name, []):
                if reg.beg < 0:
                    continue
                if reg.end < 0:
                    sub = b''
                else:
                    sub = rec.seq[reg.beg:reg.end] if reg.beg <= len(rec.seq) else b''
                cnt = _comp_counts(sub, upper_only)
                out.write(rec.name + b'\t' + ("%d\t%d\t" % (reg.beg, reg.end)).encode() + ('\t'.join(str(x) for x in cnt)).encode() + b'\n')
        else:
            cnt = _comp_counts(rec.seq, upper_only)
            out.write(rec.name + b'\t' + ("%d\t" % len(rec.seq)).encode() + ('\t'.join(str(x) for x in cnt)).encode() + b'\n')
    return 0

def _parse_sample_amount(s):
    return c_atof(s)

def cmd_sample(args):
    go = Getopt('sample', args, "s:2")
    seed = 11; two_pass = False
    for ch, val in go.opts:
        if ch == 's': seed = c_atoi(val)
        elif ch == '2': two_pass = True
    if len(go.args) < 2:
        err_bytes("\nUsage:   seqtk sample [-2] [-s seed=11] <in.fa> <frac>|<number>\n\nOptions: -s INT       RNG seed [11]\n         -2           2-pass mode: twice as slow but with much reduced memory\n\n")
        return 1
    fname = go.args[0]
    amount = _parse_sample_amount(go.args[1])
    out = sys.stdout.buffer
    if amount < 1.0:
        frac = amount
        if two_pass:
            err_bytes("[W::stk_sample] when sampling a fraction, option -2 is ignored.")
        data = read_input_data(fname, 'sample')
        rng = MT64(seed)
        for rec in iter_records(data):
            if rng.real2() < frac:
                print_record_obj(out, rec)
        return 0
    # count mode
    n_want = int(math.floor(amount + 0.5))
    if two_pass:
        if fname == '-':
            err_bytes("[E::stk_sample] in the 2-pass mode, the input cannot be STDIN.\n")
            return 1
        data = read_input_data(fname, 'sample')
        total = 0
        for rec in iter_records(data):
            total += 1
        rng = MT64(seed)
        reservoir = []
        for i in range(total):
            r = rng.real2()
            j = int(r * (i + 1))
            if i < n_want:
                reservoir.append(i)
            elif j < n_want:
                reservoir[j] = i
        chosen = set(reservoir)
        idx = 0
        for rec in iter_records(data):
            if idx in chosen:
                print_record_obj(out, rec)
            idx += 1
        return 0
    else:
        data = read_input_data(fname, 'sample')
        rng = MT64(seed)
        reservoir = []
        i = 0
        for rec in iter_records(data):
            r = rng.real2()
            j = int(r * (i + 1))
            if i < n_want:
                reservoir.append(rec)
            elif j < n_want and n_want > 0:
                reservoir[j] = rec
            i += 1
        for rec in reservoir:
            print_record_obj(out, rec)
        return 0

def _print_subseq_slice(out, rec, header_name, seq_slice, qual_slice, line_len):
    is_fq = rec.qual is not None
    out.write((b'@' if is_fq else b'>') + header_name)
    if rec.comment:
        out.write(b' ' + rec.comment)
    out.write(b'\n')
    if len(seq_slice) > 0:
        write_wrapped(out, seq_slice, line_len)
    if is_fq:
        out.write(b'+\n')
        if qual_slice is not None and len(qual_slice) > 0:
            write_wrapped(out, qual_slice, line_len)

def cmd_subseq(args):
    go = Getopt('subseq', args, "l:st")
    line_len = 0; strand_aware = False; tab = False
    for ch, val in go.opts:
        if ch == 'l': line_len = c_atoi(val)
        elif ch == 's': strand_aware = True
        elif ch == 't': tab = True
    if len(go.args) < 2:
        err_bytes("Usage:   seqtk subseq [options] <in.fa> <in.bed>|<name.list>\nOptions:\n  -t       TAB delimited output\n  -s       strand aware\n  -l INT   sequence line length [0]\nNote: Use 'samtools faidx' if only a few regions are intended.\n")
        return 1
    in_fa = go.args[0]; list_path = go.args[1]
    regions = load_regions(list_path, tab_only=strand_aware)
    if regions is None:
        err_bytes("[E::stk_subseq] failed to read the list of regions in file '%s'\n" % list_path)
        return 1
    data = read_input_data(in_fa, 'subseq', period=False)
    out = sys.stdout.buffer
    for rec in iter_records(data):
        regs = regions.get(rec.name)
        if not regs:
            continue
        for reg in regs:
            length = len(rec.seq)
            if reg.beg < 0:
                beg_eff, end_eff = 0, length
                whole = True
            else:
                whole = False
                if reg.end < 0:
                    beg_eff, end_eff = 0, length
                else:
                    beg_eff = reg.beg
                    if beg_eff >= length:
                        err_bytes("[subseq] %s: %d >= %d\n" % (rec.name.decode('latin1'), beg_eff, length))
                        continue
                    end_eff = reg.end if reg.end < length else length
            seq_slice = rec.seq[beg_eff:end_eff] if end_eff >= beg_eff else b''
            qual_slice = rec.qual[beg_eff:end_eff] if (rec.qual is not None and end_eff >= beg_eff) else (b'' if rec.qual is not None else None)
            if tab:
                if strand_aware:
                    s = revcomp(seq_slice) if reg.strand == b'-' else seq_slice
                    out.write(rec.name + b'\t' + str(beg_eff + 1).encode() + b'\t\n' + s + b'\n')
                else:
                    out.write(rec.name + b'\t' + str(beg_eff + 1).encode() + b'\t' + seq_slice + b'\n')
                continue
            if strand_aware:
                s = revcomp(seq_slice) if reg.strand == b'-' else seq_slice
                # header
                if whole:
                    hname = rec.name
                else:
                    hname = rec.name + (":%d-%d" % (beg_eff + 1, end_eff)).encode()
                is_fq = rec.qual is not None
                out.write((b'@' if is_fq else b'>') + hname)
                if rec.comment:
                    out.write(b' ' + rec.comment)
                out.write(b'\n' + s + b'\n')
                continue
            if whole:
                print_record_obj(out, rec, line_len=line_len)
            else:
                hname = rec.name + (":%d-%d" % (beg_eff + 1, end_eff)).encode()
                _print_subseq_slice(out, rec, hname, seq_slice, qual_slice, line_len)
    return 0

def _fmt_c(x, prec):
    # mimic printf %.1f / %.2f for nan/inf
    if isinstance(x, float) and math.isnan(x):
        return "-nan"
    if isinstance(x, float) and math.isinf(x):
        return "inf" if x > 0 else "-inf"
    return "%.*f" % (prec, x)

def cmd_fqchk(args):
    go = Getopt('fqchk', args, "q:")
    qthresh = 20
    for ch, val in go.opts:
        if ch == 'q': qthresh = c_atoi(val)
    if len(go.args) < 1:
        err_bytes("Usage: seqtk fqchk [-q %d] <in.fq>\nNote: use -q0 to get the distribution of all quality values\n" % qthresh)
        return 1
    data = read_input_data(go.args[0], 'fqchk')
    # per-position stats; index 0 = ALL handled separately
    pos_counts = []   # list of [A,C,G,T,N]
    pos_sumq = []
    pos_sume = []
    pos_low = []
    pos_qdist = []    # list of dict qval->count
    all_counts = [0]*5
    all_sumq = 0.0; all_sume = 0.0; all_low = 0; all_bases = 0
    all_qdist = {}
    distinct = set()
    nseq = 0; total_len = 0; min_len = None; max_len = 0
    def ensure(pos):
        while len(pos_counts) <= pos:
            pos_counts.append([0]*5); pos_sumq.append(0.0); pos_sume.append(0.0); pos_low.append(0); pos_qdist.append({})
    for rec in iter_records(data):
        if rec.qual is None:
            continue
        seq = rec.seq; qual = rec.qual
        L = len(seq)
        nseq += 1; total_len += L
        if min_len is None or L < min_len: min_len = L
        if L > max_len: max_len = L
        for i in range(L):
            ensure(i)
            u = to_upper_byte(seq[i])
            if u == 65: b = 0
            elif u == 67: b = 1
            elif u == 71: b = 2
            elif u == 84: b = 3
            else: b = 4
            pos_counts[i][b] += 1; all_counts[b] += 1
            qv = qual[i] - 33 if i < len(qual) else -33
            distinct.add(qv)
            pos_sumq[i] += qv; all_sumq += qv
            p = 10 ** (-qv / 10.0) if qv > -300 else float('inf')
            if p > 0.5: p = 0.5
            pos_sume[i] += p; all_sume += p
            if qthresh > 0 and qv < qthresh:
                pos_low[i] += 1; all_low += 1
            pos_qdist[i][qv] = pos_qdist[i].get(qv, 0) + 1
            all_qdist[qv] = all_qdist.get(qv, 0) + 1
            all_bases += 1
    out = sys.stdout.buffer
    if nseq == 0:
        out.write(b"min_len: 9223372036854775807; max_len: 0; avg_len: -nan; 0 distinct quality values\n")
    else:
        avg = total_len / nseq if nseq else float('nan')
        out.write(("min_len: %d; max_len: %d; avg_len: %s; %d distinct quality values\n" % (min_len, max_len, _fmt_c(avg, 2) if not (isinstance(avg,float) and math.isnan(avg)) else "-nan", len(distinct))).encode())
    dist_mode = qthresh <= 0
    qvals = sorted(distinct)
    header = "POS\t#bases\t%A\t%C\t%G\t%T\t%N\tavgQ\terrQ"
    if dist_mode:
        for qv in qvals: header += "\t%%Q%d" % qv
    else:
        header += "\t%low\t%high"
    out.write((header + "\n").encode())
    def row(label, counts, sumq, sume, low, qdist):
        nb = sum(counts)
        if nb == 0:
            # observed empty ALL row
            if dist_mode:
                extra = ''.join("\t-nan" for _ in qvals)
            else:
                extra = "\t-nan\t-nan"
            return "%s\t0\t-nan\t-nan\t-nan\t-nan\t-nan\t-nan\t-0.0%s\n" % (label, extra)
        pcts = [_fmt_c(100.0 * c / nb, 1) for c in counts]
        avgq = sumq / nb
        errq = -10.0 * math.log10((sume + 1e-6) / nb) if nb > 0 else -0.0
        s = "%s\t%d\t%s\t%s\t%s\t%s\t%s\t%s\t%s" % (label, nb, pcts[0], pcts[1], pcts[2], pcts[3], pcts[4], _fmt_c(avgq,1), _fmt_c(errq,1))
        if dist_mode:
            for qv in qvals:
                s += "\t" + _fmt_c(100.0 * qdist.get(qv,0) / nb, 2)
        else:
            s += "\t" + _fmt_c(100.0 * low / nb, 1) + "\t" + _fmt_c(100.0 * (nb-low) / nb, 1)
        return s + "\n"
    out.write(row("ALL", all_counts, all_sumq, all_sume, all_low, all_qdist).encode())
    for i in range(len(pos_counts)):
        if sum(pos_counts[i]) == 0:
            continue
        out.write(row(str(i+1), pos_counts[i], pos_sumq[i], pos_sume[i], pos_low[i], pos_qdist[i]).encode())
    return 0

