def _trim_bounds(qual, thresh, min_len):
    L = len(qual)
    if min_len >= 0 and L <= min_len:
        return (0, L)
    s = 0.0; max_s = 0.0; beg = 0; end = 0; tmp_beg = 0
    for i in range(L):
        q = qual[i] - 33
        if q < 3: q = 3
        p = 10 ** (-q / 10.0)
        s += thresh - p
        if s < 0:
            s = 0.0; tmp_beg = i + 1
        elif s > max_s:
            max_s = s; beg = tmp_beg; end = i + 1
    if end - beg < min_len:
        beg = end - min_len
        if beg < 0: beg = 0
        end = beg + min_len
        if end > L: end = L
    return (beg, end)

