                emit(beg, max_end)
                i = max_end; beg = max_end
            else:
                i += 1; beg = i
            score = 0.0; max_score = 0.0; max_end = beg
            continue
        i += 1
    if max_score > 0:
        emit(beg, max_end)
    return outsegs

