_mask_map = {}
for _ch,_m in [('A',1),('C',2),('G',4),('T',8),('R',5),('Y',10),('M',3),('K',12),('S',6),('W',9),('B',14),('D',13),('H',11),('V',7),('N',15),('U',15),('X',15)]:
    _mask_map[ord(_ch)] = _m
    _mask_map[ord(_ch.lower())] = _m
def iupac_mask(c):
    return _mask_map.get(c, 15)
_mask_to_char = [None,'A','C','M','G','R','S','V','T','W','Y','H','K','D','B','N']
_valid_upper = set(b'ACGTURYMKSWBDHVNX')

def cmd_mergefa(args):
    go = Getopt('mergefa', args, "q:imrh")
    qthresh = 0; f_i = False; f_m = False; f_r = False; f_h = False
    for ch, val in go.opts:
        if ch == 'q': qthresh = c_atoi(val)
        elif ch == 'i': f_i = True
        elif ch == 'm': f_m = True
        elif ch == 'r': f_r = True
        elif ch == 'h': f_h = True
    if f_i and f_m:
        err_bytes("[stk_mergefa] `-i' and `-h' cannot be applied at the same time.\n")
        return 1
    if len(go.args) < 2:
        err_bytes("\nUsage: seqtk mergefa [options] <in1.fa> <in2.fa>\n\nOptions: -q INT   quality threshold [0]\n         -i       take intersection\n         -m       convert to lowercase when one of the input base is N\n         -r       pick a random allele from het\n         -h       suppress hets in the input\n\n")
        return 1
    data1 = read_input_data(go.args[0], 'mergefa')
    data2 = read_input_data(go.args[1], 'mergefa')
    it1 = iter_records(data1); it2 = iter_records(data2)
    out = sys.stdout.buffer
    intersect = f_i or f_m
    rng = default_rng() if f_r else None
    stats = [0,0,0,0,0]  # same,diff,hom-het,het-hom,het-het
    while True:
        r1 = next(it1, None); r2 = next(it2, None)
        if r1 is None or r2 is None:
            break
        if r1.name != r2.name:
            err_bytes("[stk_mergefa] Different sequence names: %s != %s\n" % (r1.name.decode('latin1'), r2.name.decode('latin1')))
        if len(r1.seq) != len(r2.seq):
            err_bytes("[stk_mergefa] Unequal sequence length: %d != %d\n" % (len(r1.seq), len(r2.seq)))
        L = min(len(r1.seq), len(r2.seq))
        merged = bytearray()
        for i in range(L):
            c1 = r1.seq[i]; c2 = r2.seq[i]
            m1 = iupac_mask(c1); m2 = iupac_mask(c2)
            # quality handling
            lowq = False
            if qthresh > 0:
                if r1.qual is not None and i < len(r1.qual) and (r1.qual[i]-33 < qthresh): lowq = True
                if r2.qual is not None and i < len(r2.qual) and (r2.qual[i]-33 < qthresh): lowq = True
            # stats (uppercase ACGT / 2-base hets only, when not lowq)
            if not lowq:
                u1 = chr(to_upper_byte(c1)); u2 = chr(to_upper_byte(c2))
                valid = set('ACGTRMKWSY')
                # note: valid set letters are ACGT + RYMKSW
                valid = set('ACGT') | set('RYMKSW')
                if c1 in _valid_upper and c2 in _valid_upper and u1 in valid and u2 in valid:
                    p1 = bin(m1).count('1'); p2 = bin(m2).count('1')
                    if p1 == 1 and p2 == 1:
                        if m1 == m2: stats[0] += 1
                        else: stats[1] += 1
                    elif p1 == 1 and p2 == 2: stats[2] += 1
                    elif p1 == 2 and p2 == 1: stats[3] += 1
                    elif p1 == 2 and p2 == 2: stats[4] += 1
            # merge
            out_char = None
            if f_r and not intersect:
                p1 = bin(m1).count('1'); p2 = bin(m2).count('1')
                # hom in het (2-base): random between hom and het
                het_mask = None; hom_mask = None
                if p1 == 2 and p2 == 1 and (m1 & m2):
                    het_mask, hom_mask = m1, m2
                elif p2 == 2 and p1 == 1 and (m1 & m2):
                    het_mask, hom_mask = m2, m1
                if het_mask is not None:
                    if rng.real2() < 0.5:
                        out_char = _mask_to_char[hom_mask]
                    else:
                        out_char = _mask_to_char[het_mask]
                elif p1 > 1 or p2 > 1:
                    # observed: output first input's code, lowercased below
                    out_char = _mask_to_char[m1] if m1 else 'n'
                    # force lowercase
                    merged.append(ord(out_char.lower()))
                    if lowq:
                        pass
                    continue
            if out_char is None:
                rm = (m1 & m2) if intersect else (m1 | m2)
                if rm == 0:
                    merged.append(ord('x'))
                    continue
                out_char = _mask_to_char[rm]
            oc = ord(out_char)
            # case rules
            both_not_valid_upper = (c1 not in _valid_upper) and (c2 not in _valid_upper)
            either_not_valid_upper = (c1 not in _valid_upper) or (c2 not in _valid_upper)
            either_het = (bin(m1).count('1') > 1) or (bin(m2).count('1') > 1)
            lower = False
            if lowq:
                lower = True
            elif intersect:
                if f_m and (m1 == 15 or m2 == 15): lower = True
                if f_h and either_het: lower = True
                if both_not_valid_upper: lower = True
                # -m also lowers when one input is N (mask15) even without -h (above)
            else:
                if either_not_valid_upper: lower = True
                if f_h and either_het: lower = True
            if lower and 65 <= oc <= 90:
                oc += 32
            merged.append(oc)
        print_fasta60(out, r1.name, bytes(merged))
    err_bytes("[stk_mergefa] (same,diff,hom-het,het-hom,het-het)=(%d,%d,%d,%d,%d)\n" % tuple(stats))
    return 0

