    for ch, val in go.opts:
        if ch == 'q': qthresh = c_atof(val)
        elif ch == 'l': min_len = c_atoi(val)
        elif ch == 'b': trim_b = c_atoi(val)
        elif ch == 'e': trim_e = c_atoi(val)
        elif ch == 'L': trim_L = c_atoi(val)
    if len(go.args) < 1:
        err_bytes("\nUsage:   seqtk trimfq [options] <in.fq>\n\nOptions: -q FLOAT    error rate threshold (disabled by -b/-e) [0.05]\n         -l INT      maximally trim down to INT bp (disabled by -b/-e) [30]\n         -b INT      trim INT bp from left (non-zero to disable -q/-l) [0]\n         -e INT      trim INT bp from right (non-zero to disable -q/-l) [0]\n         -L INT      retain at most INT bp from the 5'-end (non-zero to disable -q/-l) [0]\n         -Q          force FASTQ output\n\n")
        return 1
    data = read_input_data(go.args[0], 'trimfq')
    out = sys.stdout.buffer
    fixed = (trim_b != 0 or trim_e != 0 or trim_L != 0)
    for rec in iter_records(data):
        seq = rec.seq; qual = rec.qual
        L = len(seq)
        if fixed:
            beg = trim_b if trim_b > 0 else 0
            end = L - trim_e if trim_e > 0 else L
            if beg > L: beg = L
            if end < beg: end = beg
            if end > L: end = L
            if trim_L != 0 and trim_L > 0:
                if end > beg + trim_L: end = beg + trim_L
        else:
            if qual is None:
                beg, end = 0, L
            else:
                beg, end = _trim_bounds(qual, qthresh, min_len)
        s_out = seq[beg:end]
        is_fq = qual is not None and len(qual) > 0
        out.write((b'@' if is_fq else b'>') + rec.name)
        if rec.comment:
            out.write(b' ' + rec.comment)
        out.write(b'\n' + s_out + b'\n')
        if is_fq:
            out.write(b'+\n' + qual[beg:end] + b'\n')
    return 0

def cmd_hety(args):
    go = Getopt('hety', args, "w:t:m")
    win = 50000; tstarts = 5; mask_lower = False
    for ch, val in go.opts:
        if ch == 'w': win = c_atoi(val)
        elif ch == 't': tstarts = c_atoi(val)
        elif ch == 'm': mask_lower = True
    if len(go.args) < 1:
        err_bytes("\nUsage:   seqtk hety [options] <in.fa>\n\nOptions: -w INT   window size [50000]\n         -t INT   # start positions in a window [5]\n         -m       treat lowercases as masked\n\n")
        return 1
    data = read_input_data(go.args[0], 'hety')
    out = sys.stdout.buffer
    if tstarts == 0:
        return 1
    step = trunc_div(win, tstarts) if tstarts != 0 else 0
    if step <= 0:
        return 1
    for rec in iter_records(data):
        seq = rec.seq; L = len(seq)
        # prefix sums of callable / het
        call_pre = [0]*(L+1); het_pre = [0]*(L+1)
        for i in range(L):
            c = seq[i]
            is_call = 0; is_het = 0
            if not (mask_lower and 97 <= c <= 122):
                u = chr(to_upper_byte(c))
                if u in 'ACGT':
                    is_call = 1
                elif u in 'RYMKSW':
                    is_call = 1; is_het = 1
            call_pre[i+1] = call_pre[i] + is_call
            het_pre[i+1] = het_pre[i] + is_het
        def counts(a, b):
            if b < a: b = a
            return (call_pre[b]-call_pre[a], het_pre[b]-het_pre[a])
        def emit(beg, end, call, het):
            if call > 0:
                rate = het / call * win if call else 0.0
                out.write(rec.name + ("\t%d\t%d\t%.2f\t%d\t%d\n" % (beg, end, rate, call, het)).encode())
        beg = 0
        # first trigger: smallest multiple of step >= win, and < L
        if step > 0:
            e = ((win + step - 1) // step) * step if win > 0 else step
            while e < L:
                call, het = counts(e - win if e - win > 0 else 0, e)
                emit(beg, e, call, het)
                beg = e
                e += step
        # final segment
        call, het = counts(beg, L)
        emit(beg, L, call, het)
    return 0

def _gc_segments(seq, target_set, frac, xdrop, min_len):
    is_t = [c in target_set for c in seq]
    ts = (1.0/frac - 1.0) if frac != 0 else float('inf')
    n = len(seq); outsegs = []
    beg = 0; i = 0; score = 0.0; max_score = 0.0; max_end = 0
    def emit(b, e):
        if e - b >= min_len:
            outsegs.append((b, e, sum(is_t[b:e])))
    while i < n:
        score += ts if is_t[i] else -1.0
        if score > max_score:
            max_score = score; max_end = i + 1
        if score < 0 or (max_score - score > xdrop):
            if max_score > 0:
                emit(beg, max_end)
                i = max_end; beg = max_end
            else:
                i += 1; beg = i
            score = 0.0; max_score = 0.0; max_end = beg
            continue
        i += 1
    if max_score > 0:
        emit(beg, max_end)
    return outsegs

