def _is_cut_target(c):
    u = chr(to_upper_byte(c))
    return u not in 'ACGTRMKWSYBDHVX'.replace('RMKWSY','RYMKSW')
    # valid non-target: ACGT + RYMKSW + BDHV + X

def _find_cut_gaps(seq, min_len, penalty):
    gaps = []
    n = len(seq)
    beg = 0; i = 0; score = 0; max_score = 0; max_end = 0
    while i < n:
        score += 1 if _is_cut_target(seq[i]) else -penalty
        if score > max_score:
            max_score = score; max_end = i + 1
        if score <= 0:
            if max_score > 0 and max_end - beg >= min_len:
                gaps.append((beg, max_end))
            if max_score > 0:
                i = max_end; beg = max_end
            else:
                i += 1; beg = i
            score = 0; max_score = 0; max_end = beg
            continue
        i += 1
    if max_score > 0 and max_end - beg >= min_len:
        gaps.append((beg, max_end))
    return gaps

def cmd_cutN(args):
    go = Getopt('cutN', args, "n:p:g")
    min_len = 1000; penalty = 10; gaps_only = False
    for ch, val in go.opts:
        if ch == 'n': min_len = c_atoi(val)
        elif ch == 'p': penalty = c_atoi(val)
        elif ch == 'g': gaps_only = True
    if len(go.args) < 1:
        err_bytes("\nUsage:   seqtk cutN [options] <in.fa>\n\nOptions: -n INT    min size of N tract [1000]\n         -p INT    penalty for a non-N [10]\n         -g        print gaps only, no sequence\n\n")
        return 1
    data = read_input_data(go.args[0], 'cutN')
    out = sys.stdout.buffer
    for rec in iter_records(data):
        seq = rec.seq; L = len(seq)
        gaps = _find_cut_gaps(seq, min_len, penalty)
        # pieces = complement
        pieces = []
        prev = 0
        for (gs, ge) in gaps:
            if gs > prev:
                pieces.append((prev, gs))
            if ge > prev: prev = ge
        if prev < L:
            pieces.append((prev, L))
        if gaps_only:
            # internal gaps between pieces, plus trailing
            for pi in range(1, len(pieces)):
                out.write(rec.name + ("\t%d\t%d\n" % (pieces[pi-1][1], pieces[pi][0])).encode())
            if pieces and pieces[-1][1] < L:
                out.write(rec.name + ("\t%d\t%d\n" % (pieces[-1][1], L)).encode())
        else:
            for (ps, pe) in pieces:
                out.write(b'>' + rec.name + (":%d-%d\n" % (ps+1, pe)).encode())
                sub = seq[ps:pe]
                for i in range(0, len(sub), 60):
                    out.write(sub[i:i+60] + b'\n')
    return 0

