#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#define NN 312
#define MM 156
#define MATRIX_A 0xB5026F5AA96619E9ULL
#define UM 0xFFFFFFFF80000000ULL
#define LM 0x7FFFFFFFULL
static uint64_t mt[NN];
static void init_mt(uint64_t seed){
 mt[0]=seed;
 for(int i=1;i<NN;i++) mt[i]=6364136223846793005ULL*(mt[i-1]^(mt[i-1]>>62))+i;
}
static void twist(void){
 for(int i=0;i<NN-MM;i++){ uint64_t x=(mt[i]&UM)|(mt[i+1]&LM); mt[i]=mt[i+MM]^(x>>1)^((x&1)?MATRIX_A:0); }
 for(int i=NN-MM;i<NN-1;i++){ uint64_t x=(mt[i]&UM)|(mt[i+1]&LM); mt[i]=mt[i+MM-NN]^(x>>1)^((x&1)?MATRIX_A:0); }
 uint64_t x=(mt[NN-1]&UM)|(mt[0]&LM); mt[NN-1]=mt[MM-1]^(x>>1)^((x&1)?MATRIX_A:0);
}
static inline uint64_t temper(uint64_t x){
 x ^= (x>>29)&0x5555555555555555ULL;
 x ^= (x<<17)&0x71D67FFFEDA60000ULL;
 x ^= (x<<37)&0xFFF7EEE000000000ULL;
 x ^= x>>43;
 return x;
}
int main(int argc,char**argv){
 const char *pat="1111111101100001011100000100100100111100010100110101010100100010111100100000001111000010111101110110";
 long maxseed=atol(argv[1]);
 int method=atoi(argv[2]); //0 top,1 low,2 bit32
 for(long seed=0;seed<=maxseed;seed++){
   init_mt(seed); twist();
   int ok=1;
   for(int i=0;i<100;i++){
     uint64_t y=temper(mt[i]);
     int b = method==0 ? (y>>63) : method==1 ? (y&1) : ((y>>32)&1);
     if(b != pat[i]-'0' && b != ('1'-pat[i])) {} // handled per polarity below
     // We check both polarities by tracking? simpler: require exact same for this run; complement run separately via pat complement compiled? We'll just exact.
     if(b != pat[i]-'0'){ ok=0; break; }
   }
   if(ok) printf("FOUND seed %ld method %d\n",seed,method);
 }
 return 0;
}
