import pathlib
p=pathlib.Path('seqtk.py');s=p.read_text()
# add Drand48 class after MT64 class (before default_rng comment)
s=s.replace("""# default RNG used by randbase / mergefa -r (seed to be refined; 11 is the
# common seqtk default and matches sample's default stream)
def default_rng():
    return MT64(11)""",
"""class Drand48:
    # glibc drand48 with default (zero) state, as used unseeded by randbase
    def __init__(self, state=0):
        self.state = state & ((1<<48)-1)
    def drand(self):
        self.state = (0x5DEECE66D * self.state + 0xB) & ((1<<48)-1)
        return self.state / 281474976710656.0

def default_rng():
    return MT64(11)""")
# randbase: use Drand48, high allele when drand<0.5
s=s.replace("    rng = default_rng()\n    for rec in iter_records(data):\n        seq = bytearray(rec.seq)", "    rng = Drand48()\n    for rec in iter_records(data):\n        seq = bytearray(rec.seq)")
s=s.replace("                chosen = a1 if rng.real2() >= 0.5 else a0", "                chosen = a1 if rng.drand() < 0.5 else a0")
p.write_text(s)
