import subprocess,random,math

def orig_bounds(qs,l=30,th=0.05):
 seq=''.join('ACGT'[i%4] for i in range(len(qs)))
 qual=''.join(chr(q+33) for q in qs)
 open('/tmp/t/trim.fq','w').write(f'@r\n{seq}\n+\n{qual}\n')
 p=subprocess.run(["./executable","trimfq","-l",str(l),"-q",str(th),"/tmp/t/trim.fq"],stdout=subprocess.PIPE)
 lines=p.stdout.decode().splitlines()
 if len(lines)<4: return (0,0)
 pairs=list(zip(seq,qual)); op=list(zip(lines[1],lines[3]))
 if not op: return (0,0)
 for s in range(len(pairs)-len(op)+1):
  if pairs[s:s+len(op)]==op: return (s,s+len(op))
 return (-1,len(op))

def xs(qs,th=0.05):
 return [th-10**(-max(q,3)/10) for q in qs]
def kadane(qs,l,th=0.05):
 L=len(qs)
 if L<=l:return (0,L)
 s=0;ms=0;beg=0;end=0;tmp=0
 for i,x in enumerate(xs(qs,th)):
  s+=x
  if s<0:s=0;tmp=i+1
  elif s>ms:ms=s;beg=tmp;end=i+1
 return beg,end
def model_extend_left(qs,l,th=0.05):
 beg,end=kadane(qs,l,th)
 if end-beg<l:
  beg=end-l
  if beg<0:beg=0
  end=beg+l
 return beg,end
def best_exact(qs,l,th=0.05):
 L=len(qs)
 if L<=l:return (0,L)
 X=xs(qs,th);pref=[0]
 for x in X:pref.append(pref[-1]+x)
 best=max(range(L-l+1),key=lambda b:pref[b+l]-pref[b])
 return best,best+l
def model_kadane_or_exact(qs,l,th=0.05):
 beg,end=kadane(qs,l,th)
 if end-beg>=l:return beg,end
 return best_exact(qs,l,th)
def model_ge(qs,l,th=0.05):
 L=len(qs)
 if L<=l:return (0,L)
 X=xs(qs,th);pref=[0]
 for x in X:pref.append(pref[-1]+x)
 best=None;bestv=None
 minpref=float('inf');minb=0
 for end in range(l,L+1):
  nb=end-l
  if pref[nb]<minpref:minpref=pref[nb];minb=nb
  v=pref[end]-minpref
  if bestv is None or v>bestv:bestv=v;best=(minb,end)
 return best
def model_exact_always(qs,l,th=0.05):
 # if kadane segment >=l use it else best exact (same as kadane_or_exact)
 return model_kadane_or_exact(qs,l,th)

models={'extend_left':model_extend_left,'ge':model_ge,'kad_or_exact':model_kadane_or_exact}
counts={k:0 for k in models}; total=0; examples={k:[] for k in models}
rng=random.Random(1)
for trial in range(200):
 L=rng.randint(31,80)
 # qualities biased: choices 0,5,10,20,30,40
 qs=[rng.choice([0,0,5,10,13,20,30,40]) for _ in range(L)]
 l=rng.choice([5,10,20,30])
 o=orig_bounds(qs,l)
 total+=1
 for name,fn in models.items():
  if fn(qs,l)==o: counts[name]+=1
  elif len(examples[name])<3: examples[name].append((qs,l,o,fn(qs,l)))
print('total',total,'matches',counts)
for k,v in examples.items(): print(k,v[:1])
